cd /workspace/graphic; python3 - <<'EOF'
import json,re
p='js/template.js'; s=open(p).read()
a=s.index('var NOACG_ANIM = {'); b=s.index('\n};',a)
d=json.loads(s[a+len('var NOACG_ANIM = '):b+2])
enter={"name":"Enter","duration":1.0,"ease":"expo.out","layers":{
 ".lower-third-box":{"clipPath":[{"time":0,"value":"inset(0 100% 0 0)"},{"time":0.6,"value":"inset(0 0% 0 0)"}],
                     "opacity":[{"time":0,"value":0},{"time":0.25,"value":1}]},
 "#f0":{"yPercent":[{"time":0.25,"value":110},{"time":0.85,"value":0}]},
 "#f1":{"yPercent":[{"time":0.4,"value":110},{"time":1.0,"value":0}]}}}
out={"name":"Out","duration":0.6,"ease":"power3.in","layers":{
 "#f0":{"yPercent":[{"time":0,"value":0},{"time":0.3,"value":110}]},
 "#f1":{"yPercent":[{"time":0.05,"value":0},{"time":0.35,"value":110}]},
 ".lower-third-box":{"clipPath":[{"time":0.25,"value":"inset(0 0% 0 0%)"},{"time":0.6,"value":"inset(0 100% 0 0%)"}],
                     "opacity":[{"time":0.4,"value":1},{"time":0.6,"value":0}]}}}
d["steps"]=[enter,out]
s=s[:a]+'var NOACG_ANIM = '+json.dumps(d,indent=2)[:-1]+'}'+s[b+2:]
end=s.index('/* == END ANIMATION == */')+len('/* == END ANIMATION == */')
fit='''

// ---- Long-name fit ladder (outside the ANIMATION region) ----
// Each line first tries its full size; if it would wrap it steps down to fit1, then fit2.
// Only past the last rung is it allowed to wrap (balanced rows, the panel grows upward).
var LT_FIT_RUNGS = ['', 'lower-third-fit1', 'lower-third-fit2'];
var ltOverflow = [];
function ltLines(el) {
  var lh = parseFloat(window.getComputedStyle(el).lineHeight) || 1;
  return Math.round(el.offsetHeight / lh);
}
function ltFit(id, maxLines) {
  var el = document.getElementById(id);
  if (!el) return;
  var i, lines = 1;
  for (i = 0; i < LT_FIT_RUNGS.length; i++) {
    el.classList.remove('lower-third-fit1');
    el.classList.remove('lower-third-fit2');
    if (LT_FIT_RUNGS[i]) el.classList.add(LT_FIT_RUNGS[i]);
    lines = ltLines(el);
    if (lines <= 1) return;
  }
  if (lines > maxLines) ltOverflow.push(id);
}
function fitPlacedText() {
  ltOverflow = [];
  ltFit('f0', 2);
  ltFit('f1', 2);
}
function noacgTextOverflow() { return ltOverflow.slice(); }
(function () {
  function go() { fitPlacedText(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', go);
  else go();
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(go);
  window.addEventListener('load', go);
})();
'''
s=s[:end]+fit+s[end:]
open(p,'w').write(s)
EOF
